[ "$(BOOKINGS=$t bash src/book.sh aoi 2026/12/01 10:00 11:00 x 2>&1 >/dev/null)" = "bad date: 2026/12/01 (expected YYYY-MM-DD)" ] || { echo "bad date message differs"; fail=1; }
